    Trip tr = getTrip();
    Date bDate = getBookingDate();
    int seats = getNumberOfSeats();

    // Step 1
    if (cust == null || tr == null || bDate == null)
    {
      return false;
    }

    // Step 2
    if (tr.getNumberOfSeats() < seats)
    {
      return false;
    }

    try
    {
      SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm");
      Date tripDeparture = sdf.parse(tr.getDepartureTime());

      // Step 4
      long diffMillis = tripDeparture.getTime() - bDate.getTime();
      if (diffMillis <= 2L * 60L * 60L * 1000L)
      {
        return false;
      }

      // Step 5
      String tripDepartureDay = tr.getDepartureTime().substring(0, 10);
      Date thisTripArrival = sdf.parse(tr.getArrivalTime());
      for (Booking b : cust.getBookings())
      {
        if (b == this)
        {
          continue;
        }
        Trip bTrip = b.getTrip();
        if (bTrip == null)
        {
          continue;
        }
        String bDepartureDay = bTrip.getDepartureTime();
        if (bDepartureDay == null)
        {
          continue;
        }
        bDepartureDay = bDepartureDay.substring(0, 10);
        if (bDepartureDay.equals(tripDepartureDay))
        {
          Date bDeparture = sdf.parse(bTrip.getDepartureTime());
          Date bArrival = sdf.parse(bTrip.getArrivalTime());
          // Overlap: aStart < bEnd AND bStart < aEnd
          if (tripDeparture.before(bArrival) && bDeparture.before(thisTripArrival))
          {
            return false;
          }
        }
      }
    }
    catch (ParseException e)
    {
      return false;
    }

    // Step 6
